import{J as e,n as t,ot as n,q as r}from"./chunks/framework.1lTNTJZP.js";var i=JSON.parse(`{"title":"Class: SampleContext","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: SampleContext"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/SampleContext"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/SampleContext"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/worldgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/worldgen/classes/SampleContext.md","filePath":"api/@jsprismarine/worldgen/classes/SampleContext.md","lastUpdated":1794206055000}`),a={name:`api/@jsprismarine/worldgen/classes/SampleContext.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/worldgen</a> / SampleContext</p><h1 id="class-samplecontext" tabindex="-1">Class: SampleContext <a class="header-anchor" href="#class-samplecontext" aria-label="Permalink to “Class: SampleContext”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L134" target="_blank" rel="noreferrer">density/SampleContext.ts:134</a></p><p>The per-chunk state a compiled density function tree reads while sampling.</p><p>Java keeps the same split: the function tree is immutable and shared across chunks and threads, and everything mutable or chunk-specific lives here. The three overrides are the seams the world blender and the structure beard hook into.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new SampleContext</strong>(): <code>SampleContext</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>SampleContext</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="beardifier" tabindex="-1">beardifier <a class="header-anchor" href="#beardifier" aria-label="Permalink to “beardifier”">​</a></h3><blockquote><p><strong>beardifier</strong>: <a href="./../#densitysampler"><code>DensitySampler</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L150" target="_blank" rel="noreferrer">density/SampleContext.ts:150</a></p><p>Replaces <code>beardifier</code>, which is 0 where no structure pushes terrain around.</p><hr><h3 id="blendalpha" tabindex="-1">blendAlpha <a class="header-anchor" href="#blendalpha" aria-label="Permalink to “blendAlpha”">​</a></h3><blockquote><p><strong>blendAlpha</strong>: <a href="./../#densitysampler"><code>DensitySampler</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L143" target="_blank" rel="noreferrer">density/SampleContext.ts:143</a></p><p>Replaces <code>blend_alpha</code>, which is 1 outside a blending region. The world blender sets it when a chunk borders terrain generated by an older version. This hook must be independent of y, matching Java&#39;s horizontal blending value, because density caches may share it down a column.</p><hr><h3 id="blenddensity" tabindex="-1">blendDensity <a class="header-anchor" href="#blenddensity" aria-label="Permalink to “blendDensity”">​</a></h3><blockquote><p><strong>blendDensity</strong>: ((<code>x</code>, <code>y</code>, <code>z</code>, <code>density</code>) =&gt; <code>number</code>) | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L152" target="_blank" rel="noreferrer">density/SampleContext.ts:152</a></p><p>Post-processes <code>blend_density</code>, which is the identity outside a blending region.</p><hr><h3 id="blendoffset" tabindex="-1">blendOffset <a class="header-anchor" href="#blendoffset" aria-label="Permalink to “blendOffset”">​</a></h3><blockquote><p><strong>blendOffset</strong>: <a href="./../#densitysampler"><code>DensitySampler</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L148" target="_blank" rel="noreferrer">density/SampleContext.ts:148</a></p><p>Replaces <code>blend_offset</code>, which is 0 outside a blending region. This hook must be independent of y so a cache can safely reuse its value down a column.</p><hr><h3 id="interpolationbuffersenabled" tabindex="-1">interpolationBuffersEnabled <a class="header-anchor" href="#interpolationbuffersenabled" aria-label="Permalink to “interpolationBuffersEnabled”">​</a></h3><blockquote><p><strong>interpolationBuffersEnabled</strong>: <code>boolean</code> = <code>false</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L136" target="_blank" rel="noreferrer">density/SampleContext.ts:136</a></p><p>Enabled only while a caller walks complete interpolation cells in cell-major order.</p><hr><h3 id="interpolationcellversions" tabindex="-1">interpolationCellVersions <a class="header-anchor" href="#interpolationcellversions" aria-label="Permalink to “interpolationCellVersions”">​</a></h3><blockquote><p><strong>interpolationCellVersions</strong>: <code>Uint32Array</code>&lt;<code>ArrayBuffer</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L178" target="_blank" rel="noreferrer">density/SampleContext.ts:178</a></p><p>The current interpolation-cell version per node id, used to invalidate y-stage entries.</p><hr><h3 id="interpolationcorners" tabindex="-1">interpolationCorners <a class="header-anchor" href="#interpolationcorners" aria-label="Permalink to “interpolationCorners”">​</a></h3><blockquote><p><strong>interpolationCorners</strong>: <code>Float64Array</code>&lt;<code>ArrayBuffer</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L162" target="_blank" rel="noreferrer">density/SampleContext.ts:162</a></p><p>The eight corners of each <code>interpolated</code> node&#39;s current cell, eight doubles per node id, ordered x fastest, then y, then z.</p><p>Public and flat because the compiled closure reads it on every sample; <a href="#interpolationcell">SampleContext.interpolationCell</a> is the only thing that may resize it, so a caller reads the field after that call rather than holding it across one.</p><hr><h3 id="interpolationxcache" tabindex="-1">interpolationXCache <a class="header-anchor" href="#interpolationxcache" aria-label="Permalink to “interpolationXCache”">​</a></h3><blockquote><p><strong>interpolationXCache</strong>: <code>Float64Array</code>&lt;<code>ArrayBuffer</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L169" target="_blank" rel="noreferrer">density/SampleContext.ts:169</a></p><p>The current horizontal interpolation stage per node id: one x-in-cell key followed by the four x-interpolated corner values. The key is invalidated when <a href="#interpolationcell">SampleContext.interpolationCell</a> moves to another cell.</p><hr><h3 id="interpolationycache" tabindex="-1">interpolationYCache <a class="header-anchor" href="#interpolationycache" aria-label="Permalink to “interpolationYCache”">​</a></h3><blockquote><p><strong>interpolationYCache</strong>: <code>Float64Array</code>&lt;<code>ArrayBuffer</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L175" target="_blank" rel="noreferrer">density/SampleContext.ts:175</a></p><p>A 16-slot, direct-mapped cache for the y-interpolated corner pairs, 5 doubles per slot: cell version, x offset, y offset, and two values. Exact keys make collisions recompute.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="cell" tabindex="-1">cell() <a class="header-anchor" href="#cell" aria-label="Permalink to “cell()”">​</a></h3><blockquote><p><strong>cell</strong>(<code>id</code>): <code>CacheCell</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L190" target="_blank" rel="noreferrer">density/SampleContext.ts:190</a></p><p>Returns the memo slot a compiled <code>cache</code> node owns, creating it on first use.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>CacheCell</code></p><hr><h3 id="cornercache" tabindex="-1">cornerCache() <a class="header-anchor" href="#cornercache" aria-label="Permalink to “cornerCache()”">​</a></h3><blockquote><p><strong>cornerCache</strong>(<code>id</code>): <a href="./CornerCache.html"><code>CornerCache</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L199" target="_blank" rel="noreferrer">density/SampleContext.ts:199</a></p><p>Returns the corner cache a compiled <code>interpolated</code> node fills, creating it on first use.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-1" tabindex="-1">id <a class="header-anchor" href="#id-1" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./CornerCache.html"><code>CornerCache</code></a></p><hr><h3 id="interpolationbuffer" tabindex="-1">interpolationBuffer() <a class="header-anchor" href="#interpolationbuffer" aria-label="Permalink to “interpolationBuffer()”">​</a></h3><blockquote><p><strong>interpolationBuffer</strong>(<code>id</code>, <code>valueCount</code>): <code>Float64Array</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L257" target="_blank" rel="noreferrer">density/SampleContext.ts:257</a></p><p>Returns a reusable cell output buffer, allocating it on the node&#39;s first cell.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-2" tabindex="-1">id <a class="header-anchor" href="#id-2" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h5 id="valuecount" tabindex="-1">valueCount <a class="header-anchor" href="#valuecount" aria-label="Permalink to “valueCount”">​</a></h5><p><code>number</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Float64Array</code></p><hr><h3 id="interpolationbufferscratch" tabindex="-1">interpolationBufferScratch() <a class="header-anchor" href="#interpolationbufferscratch" aria-label="Permalink to “interpolationBufferScratch()”">​</a></h3><blockquote><p><strong>interpolationBufferScratch</strong>(<code>id</code>, <code>valueCount</code>): <code>Float64Array</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L269" target="_blank" rel="noreferrer">density/SampleContext.ts:269</a></p><p>Returns reusable corner-stage values for filling an interpolation cell.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-3" tabindex="-1">id <a class="header-anchor" href="#id-3" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h5 id="valuecount-1" tabindex="-1">valueCount <a class="header-anchor" href="#valuecount-1" aria-label="Permalink to “valueCount”">​</a></h5><p><code>number</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Float64Array</code></p><hr><h3 id="interpolationbuffervalue" tabindex="-1">interpolationBufferValue() <a class="header-anchor" href="#interpolationbuffervalue" aria-label="Permalink to “interpolationBufferValue()”">​</a></h3><blockquote><p><strong>interpolationBufferValue</strong>(<code>id</code>, <code>x</code>, <code>y</code>, <code>z</code>, <code>index</code>): <code>number</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L243" target="_blank" rel="noreferrer">density/SampleContext.ts:243</a></p><p>Returns a filled node buffer value when its cell origin still matches the query.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-4" tabindex="-1">id <a class="header-anchor" href="#id-4" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="index" tabindex="-1">index <a class="header-anchor" href="#index" aria-label="Permalink to “index”">​</a></h5><p><code>number</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code> | <code>undefined</code></p><hr><h3 id="interpolationcell" tabindex="-1">interpolationCell() <a class="header-anchor" href="#interpolationcell" aria-label="Permalink to “interpolationCell()”">​</a></h3><blockquote><p><strong>interpolationCell</strong>(<code>id</code>, <code>x</code>, <code>y</code>, <code>z</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L214" target="_blank" rel="noreferrer">density/SampleContext.ts:214</a></p><p>Makes one interpolation cell current and says whether its corners are already in place.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-5" tabindex="-1">id <a class="header-anchor" href="#id-5" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h5 id="x-1" tabindex="-1">x <a class="header-anchor" href="#x-1" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-1" tabindex="-1">y <a class="header-anchor" href="#y-1" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-1" tabindex="-1">z <a class="header-anchor" href="#z-1" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>True when <a href="#interpolationcorners">SampleContext.interpolationCorners</a> still holds this cell&#39;s eight corners, false when the caller has to write them. A false answer has already recorded the new origin, so the next sample inside the cell gets a true one.</p><hr><h3 id="markinterpolationbufferfilled" tabindex="-1">markInterpolationBufferFilled() <a class="header-anchor" href="#markinterpolationbufferfilled" aria-label="Permalink to “markInterpolationBufferFilled()”">​</a></h3><blockquote><p><strong>markInterpolationBufferFilled</strong>(<code>id</code>, <code>x</code>, <code>y</code>, <code>z</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L280" target="_blank" rel="noreferrer">density/SampleContext.ts:280</a></p><p>Records a cell origin only after its output buffer has been filled completely.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id-6" tabindex="-1">id <a class="header-anchor" href="#id-6" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><h5 id="x-2" tabindex="-1">x <a class="header-anchor" href="#x-2" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-2" tabindex="-1">y <a class="header-anchor" href="#y-2" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-2" tabindex="-1">z <a class="header-anchor" href="#z-2" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="reset" tabindex="-1">reset() <a class="header-anchor" href="#reset" aria-label="Permalink to “reset()”">​</a></h3><blockquote><p><strong>reset</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/106770bd71c69d27391fc4faaf5e66fac5c1cc47/packages/worldgen/src/density/SampleContext.ts#L294" target="_blank" rel="noreferrer">density/SampleContext.ts:294</a></p><p>Drops every memoized value.</p><p>A caller that walks more than one chunk with one context has to do this between them, or the corner caches keep serving the previous chunk&#39;s working set.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,159)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};